    qp = s->current_picture.qscale_table[mb_xy];
    qp0 = s->current_picture.qscale_table[mb_xy-1];
    qp1 = s->current_picture.qscale_table[h->top_mb_xy];
     qpc = get_chroma_qp( h, qp );
     qpc0 = get_chroma_qp( h, qp0 );
     qpc1 = get_chroma_qp( h, qp1 );
